--
-- Table structure for table `movement`
--

DROP TABLE IF EXISTS `movement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `movement` (
  `id` varchar(36) NOT NULL,
  `item_id` varchar(36) DEFAULT NULL,
  `equipment_id` varchar(36) DEFAULT NULL,
  `movement_event_type` enum('RECEIVE','ISSUE','ADJUSTMENT','TRANSFER_OUT','TRANSFER_IN','LOAN_OUT','LOAN_RETURN','DISTRIBUTE_OUT','DISTRIBUTE_IN','MAINTENANCE_IN','MAINTENANCE_OUT') NOT NULL,
  `qty` decimal(12,4) NOT NULL DEFAULT '1.0000',
  `unit` varchar(20) DEFAULT NULL,
  `movement_classification` enum('BALKIR','KOMUNITY','TRANSITO') DEFAULT NULL,
  `specific_location_name` varchar(255) DEFAULT NULL,
  `from_warehouse_id` varchar(36) DEFAULT NULL,
  `to_warehouse_id` varchar(36) DEFAULT NULL,
  `organization_id` varchar(36) DEFAULT NULL,
  `notes` text,
  `pic_id` varchar(36) DEFAULT NULL,
  `movement_reference_type` enum('LENDING','DISTRIBUTION','MAINTENANCE') DEFAULT NULL,
  `reference_id` varchar(36) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT (now()),
  `condition_at_arrival` enum('BAIK','RUSAK_RINGAN','RUSAK_BERAT') DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `movement_pic_id_user_id_fk` (`pic_id`),
  KEY `movement_item_idx` (`item_id`),
  KEY `movement_equipment_idx` (`equipment_id`),
  KEY `movement_from_warehouse_idx` (`from_warehouse_id`),
  KEY `movement_to_warehouse_idx` (`to_warehouse_id`),
  KEY `movement_organization_idx` (`organization_id`),
  KEY `movement_reference_idx` (`reference_id`),
  CONSTRAINT `movement_equipment_id_equipment_id_fk` FOREIGN KEY (`equipment_id`) REFERENCES `equipment` (`id`),
  CONSTRAINT `movement_from_warehouse_id_warehouse_id_fk` FOREIGN KEY (`from_warehouse_id`) REFERENCES `warehouse` (`id`),
  CONSTRAINT `movement_item_id_item_id_fk` FOREIGN KEY (`item_id`) REFERENCES `item` (`id`),
  CONSTRAINT `movement_organization_id_organization_id_fk` FOREIGN KEY (`organization_id`) REFERENCES `organization` (`id`),
  CONSTRAINT `movement_pic_id_user_id_fk` FOREIGN KEY (`pic_id`) REFERENCES `user` (`id`),
  CONSTRAINT `movement_to_warehouse_id_warehouse_id_fk` FOREIGN KEY (`to_warehouse_id`) REFERENCES `warehouse` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

