CREATE TABLE `stock` (
  `id` varchar(36) NOT NULL,
  `item_id` varchar(36) DEFAULT NULL,
  `warehouse_id` varchar(36) DEFAULT NULL,
  `qty` decimal(12,4) NOT NULL DEFAULT '0.0000',
  `updated_at` timestamp NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `stock_unique_idx` (`item_id`,`warehouse_id`),
  KEY `stock_warehouse_id_warehouse_id_fk` (`warehouse_id`),
  KEY `stock_item_idx` (`item_id`),
  CONSTRAINT `stock_item_id_item_id_fk` FOREIGN KEY (`item_id`) REFERENCES `item` (`id`) ON DELETE CASCADE,
  CONSTRAINT `stock_warehouse_id_warehouse_id_fk` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
